"""Client-side hard spend cap for the Meta Model API."""
import json
import logging
from pathlib import Path
from typing import Any, NamedTuple

import httpx
import openai

logger: logging.Logger = logging.getLogger(__name__)

STOP_AT_USD: float = 140.0
LEDGER_FILE: Path = Path(__file__).parent / ".muse_spend.jsonl"
METERED_PATHS: tuple[str, ...] = ("/v1/responses", "/v1/chat/completions")
TRANSCRIBE_PATH: str = "/v1/asr/transcribe"
TRANSCRIBE_MODEL: str = "muse-voice-transcribe-1.0"
TRANSCRIBE_USD_PER_HOUR: float = 0.18
TRANSCRIBE_WORST_CASE_USD: float = 0.03


class Price(NamedTuple):
    """USD per 1M tokens."""

    input: float
    cached_input: float
    output: float


PRICES: dict[str, Price] = {
    "muse-wonder-1.0": Price(4.00, 0.20, 20.00),
    "muse-spark-1.3": Price(1.25, 0.15, 4.25),
    "muse-spark-1.2": Price(1.25, 0.15, 4.25),
    "muse-spark-1.1": Price(1.25, 0.15, 4.25),
    "muse-spark-1.3-contributor": Price(0.10, 0.002, 0.20),
    "muse-spark-1.2-contributor": Price(0.10, 0.002, 0.20),
}


def spent_usd(ledger: Path = LEDGER_FILE) -> float:
    """Sum the JSONL ledger; 0.0 if missing."""
    try:
        text: str = ledger.read_text(encoding="utf-8")
    except FileNotFoundError:
        return 0.0
    total: float = 0.0
    for line in text.splitlines():
        if not line.strip():
            continue
        try:
            row: Any = json.loads(line)
        except Exception as exc:
            raise ValueError(f"spend ledger is unreadable: invalid JSON: {line!r}") from exc
        if not isinstance(row, dict):
            raise ValueError(f"spend ledger is unreadable: not an object: {line!r}")
        usd_val: Any = row.get("usd")
        if isinstance(usd_val, bool) or not isinstance(usd_val, (int, float)):
            raise ValueError(f"spend ledger is unreadable: bad usd value: {line!r}")
        total += float(usd_val)
    return total


def record_spend(ledger: Path, model: str, usd: float) -> None:
    """Append one spend line; append-only for concurrent processes."""
    ledger.parent.mkdir(parents=True, exist_ok=True)
    row: str = json.dumps({"model": model, "usd": usd})
    with open(ledger, "a", encoding="utf-8") as fh:
        fh.write(row + "\n")


def max_output_tokens(body: dict[str, Any]) -> int | None:
    """First truthy max-output value or None."""
    for key in ("max_output_tokens", "max_completion_tokens", "max_tokens"):
        val: Any = body.get(key)
        if val:
            try:
                return int(val)
            except Exception:
                return None
    return None


def refusal_reason(path: str, body: dict[str, Any]) -> str | None:
    """Return refusal message or None if the call can be metered."""
    if path not in METERED_PATHS:
        return f"{path} has no price rule in budget.py"
    model: Any = body.get("model")
    if not isinstance(model, str) or model not in PRICES:
        return f"model {model!r} has no price in budget.py"
    if body.get("stream") or body.get("background"):
        return "streaming and background calls cannot be metered"
    tools: Any = body.get("tools")
    if isinstance(tools, list):
        for tool in tools:
            if not isinstance(tool, dict):
                return f"built-in tool {tool!r} has no price in budget.py"
            ttype: Any = tool.get("type", "")
            if isinstance(ttype, str) and "search" in ttype.lower():
                return "built-in search tools are billed per query and cannot be metered"
            if ttype != "function":
                return f"built-in tool {ttype!r} has no price in budget.py"
    if not max_output_tokens(body):
        return "set max_output_tokens so the worst-case cost is known"
    return None


def worst_case_usd(body: dict[str, Any], request_bytes: int) -> float:
    """Worst-case cost: input bytes plus max output tokens."""
    model: Any = body.get("model", "")
    price: Price | None = PRICES.get(model) if isinstance(model, str) else None
    if price is None:
        return 0.0
    max_out: int = max_output_tokens(body) or 0
    in_tokens: float = float(request_bytes) / 2.0
    return in_tokens / 1_000_000 * price.input + max_out / 1_000_000 * price.output


def actual_usd(model: str, usage: dict[str, Any]) -> float:
    """Actual cost from usage; missing counts raise KeyError."""
    price: Price = PRICES[model]
    if "input_tokens" in usage:
        in_total: Any = usage["input_tokens"]
    elif "prompt_tokens" in usage:
        in_total = usage["prompt_tokens"]
    else:
        raise KeyError("input_tokens")
    if "output_tokens" in usage:
        out_total: Any = usage["output_tokens"]
    elif "completion_tokens" in usage:
        out_total = usage["completion_tokens"]
    else:
        raise KeyError("output_tokens")
    if not isinstance(in_total, (int, float)):
        raise KeyError("input_tokens")
    if not isinstance(out_total, (int, float)):
        raise KeyError("output_tokens")
    cached: int = 0
    for key in ("input_tokens_details", "prompt_tokens_details"):
        det: Any = usage.get(key)
        if isinstance(det, dict) and isinstance(det.get("cached_tokens"), (int, float)):
            cached = int(det["cached_tokens"])
            break
    rest: float = float(in_total) - float(cached)
    return rest / 1_000_000 * price.input + float(cached) / 1_000_000 * price.cached_input + float(out_total) / 1_000_000 * price.output


def refusal_response(request: httpx.Request, message: str) -> httpx.Response:
    """Local 402 refusal; never raise from send."""
    body: bytes = json.dumps({"error": {"code": "local_budget_guard", "message": f"Blocked locally: {message}"}}).encode("utf-8")
    return httpx.Response(402, content=body, headers={"Content-Type": "application/json"}, request=request)


def _duration_ms(data: Any) -> float | None:
    """Find audio duration ms in a transcribe response."""
    if isinstance(data, dict):
        for key in ("audioDurationMs", "audio_duration_ms", "durationMs", "duration_ms"):
            val: Any = data.get(key)
            if isinstance(val, (int, float)):
                return float(val)
        usage: Any = data.get("usage")
        if isinstance(usage, dict):
            found: float | None = _duration_ms(usage)
            if found is not None:
                return found
    return None


def _read_body(resp: httpx.Response) -> None:
    """Read response body, ignoring errors."""
    try:
        resp.read()
    except Exception:
        pass


class BudgetedHttpClient(openai.DefaultHttpxClient):
    """httpx client that enforces a hard spend cap locally."""

    def __init__(self, *, ledger: Path = LEDGER_FILE, limit_usd: float = STOP_AT_USD, **kwargs: Any) -> None:
        super().__init__(**kwargs)
        self._ledger: Path = ledger
        self._limit_usd: float = limit_usd

    def send(self, request: httpx.Request, **kwargs: Any) -> httpx.Response:
        if request.method.upper() == "GET":
            return super().send(request, **kwargs)
        path: str = request.url.path
        if path == TRANSCRIBE_PATH:
            return self._send_transcribe(request, **kwargs)
        return self._send_metered(request, **kwargs)

    def _send_transcribe(self, request: httpx.Request, **kwargs: Any) -> httpx.Response:
        try:
            spent: float = spent_usd(self._ledger)
        except ValueError:
            return refusal_response(request, "spend ledger is unreadable, request blocked")
        if spent + TRANSCRIBE_WORST_CASE_USD > self._limit_usd:
            return refusal_response(request, "spending limit exceeded for transcription")
        resp: httpx.Response = super().send(request, **kwargs)
        _read_body(resp)
        if not 200 <= resp.status_code < 300:
            return resp
        try:
            ms: float | None = _duration_ms(resp.json())
            if ms is None:
                raise ValueError("no duration")
            cost: float = ms / 3_600_000 * TRANSCRIBE_USD_PER_HOUR
        except Exception:
            cost = TRANSCRIBE_WORST_CASE_USD
        try:
            record_spend(self._ledger, TRANSCRIBE_MODEL, cost)
        except Exception:
            logger.exception("record transcribe spend failed")
        return resp

    def _send_metered(self, request: httpx.Request, **kwargs: Any) -> httpx.Response:
        try:
            request.read()
        except Exception:
            pass
        try:
            raw: bytes = request.content or b""
        except Exception:
            return refusal_response(request, "request body is not JSON and cannot be priced")
        try:
            current_spent: float = spent_usd(self._ledger)
        except ValueError:
            return refusal_response(request, "spend ledger is unreadable, request blocked")
        try:
            body: Any = json.loads(raw.decode("utf-8"))
            if not isinstance(body, dict):
                raise ValueError("not a dict")
        except Exception:
            return refusal_response(request, "request body is not JSON and cannot be priced")
        reason: str | None = refusal_reason(request.url.path, body)
        if reason is not None:
            return refusal_response(request, reason)
        worst: float = worst_case_usd(body, len(raw))
        if current_spent + worst > self._limit_usd:
            return refusal_response(request, "spending limit exceeded for this call")
        resp: httpx.Response = super().send(request, **kwargs)
        _read_body(resp)
        if not 200 <= resp.status_code < 300:
            return resp
        model: str = str(body.get("model", ""))
        try:
            data: Any = resp.json()
            usage: Any = data.get("usage") if isinstance(data, dict) else None
            if not isinstance(usage, dict):
                raise ValueError("missing usage")
            cost: float = actual_usd(model, usage)
        except Exception:
            cost = worst
        try:
            record_spend(self._ledger, model, cost)
        except Exception:
            logger.exception("record spend failed")
        return resp


if __name__ == "__main__":
    total: float = spent_usd()
    print(f"Spent ${total:.4f} of the ${STOP_AT_USD:.2f} limit")

"""Generate project files with Muse. Model output is untrusted."""
import argparse
import json
import logging
import sys
from pathlib import Path
from typing import Any

from muse_client import DEFAULT_MODEL, create_client
from budget import spent_usd

logger: logging.Logger = logging.getLogger(__name__)
ROOT: Path = Path(__file__).parent
SPEC_PATH: Path = ROOT / "spec" / "blackout_spec.md"
RUNS_DIR: Path = ROOT / "muse_runs"
INFRA_FILES: frozenset[str] = frozenset({"budget.py", "muse_client.py", "build_with_muse.py", "check_connection.py", "test_budget.py", "test_muse_client.py", "test_build_with_muse.py", "requirements.txt", ".env.example", ".gitignore"})


def is_allowed_path(path: str, allow_infra: bool = False) -> bool:
    """Check whether model output may write to path."""
    if not path:
        return False
    if path.startswith("/"):
        return False
    if "\\" in path or ":" in path:
        return False
    parts: list[str] = path.split("/")
    if any(p == ".." for p in parts):
        return False
    if path == ".env" or path.startswith(".env/"):
        return False
    if path == ".git" or path.startswith(".git/"):
        return False
    if path == ".github" or path.startswith(".github/"):
        return False
    if path == "README.md":
        return True
    for prefix in ("app/", "tests/", "docs/"):
        if path.startswith(prefix) and len(path) > len(prefix) and not path.endswith("/"):
            return True
    if allow_infra and path in INFRA_FILES:
        return True
    return False


def write_files(files: list[dict[str, str]], root: Path = ROOT, allow_infra: bool = False) -> list[str]:
    """Validate all paths, then write them with LF newlines."""
    bad: list[str] = [str(f.get("path", "")) for f in files if not is_allowed_path(str(f.get("path", "")), allow_infra)]
    if bad:
        raise ValueError(f"rejected paths: {', '.join(bad)}")
    written: list[str] = []
    for item in files:
        rel: str = str(item.get("path", ""))
        content: str = str(item.get("content", ""))
        content = content.replace("\r\n", "\n").replace("\r", "\n")
        dest: Path = root / rel
        dest.parent.mkdir(parents=True, exist_ok=True)
        with open(dest, "w", encoding="utf-8", newline="\n") as fh:
            fh.write(content)
        written.append(rel)
    return written


def generate(model: str, prompt: str) -> tuple[list[dict[str, str]], str]:
    """Call Muse and parse the files JSON."""
    schema: dict[str, Any] = {"type": "object", "additionalProperties": False, "properties": {"files": {"type": "array", "items": {"type": "object", "additionalProperties": False, "properties": {"path": {"type": "string"}, "content": {"type": "string"}}, "required": ["path", "content"]}}}, "required": ["files"]}
    client: Any = create_client().with_options(timeout=1800, max_retries=0)
    resp: Any = client.responses.create(model=model, input=[{"role": "user", "content": prompt}], max_output_tokens=60000, reasoning={"effort": "medium"}, text={"format": {"type": "json_schema", "name": "project_files", "schema": schema, "strict": True}})
    raw: str = str(resp.output_text)
    data: Any = json.loads(raw)
    files: Any = data.get("files")
    if not isinstance(files, list):
        raise ValueError("model output has no files list")
    out: list[dict[str, str]] = [{"path": str(f["path"]), "content": str(f["content"])} for f in files]
    return out, raw


def _collect_project(allow_infra: bool = False, root: Path = ROOT) -> str:
    """Dump current project files as text."""
    rels: list[str] = ["README.md"]
    for base in ("app", "tests", "docs"):
        bdir: Path = root / base
        if bdir.is_dir():
            for p in sorted(bdir.rglob("*")):
                if p.is_file():
                    if "__pycache__" in p.parts:
                        continue
                    rels.append(str(p.relative_to(root).as_posix()))
    if allow_infra:
        for name in sorted(INFRA_FILES):
            if name not in rels and (root / name).is_file():
                rels.append(name)
    chunks: list[str] = []
    for rel in rels:
        try:
            content: str = (root / rel).read_text(encoding="utf-8")
        except FileNotFoundError:
            continue
        except IsADirectoryError:
            continue
        except OSError:
            continue
        except UnicodeDecodeError as exc:
            logger.warning("skipping non-utf8 file %s: %s", rel, exc)
            continue
        chunks.append(f"--- {rel} ---\n{content}")
    return "\n\n".join(chunks)


def build_input(feedback: str | None, allow_infra: bool = False, root: Path = ROOT) -> str:
    """Build the model prompt from spec, project, and feedback."""
    spec_file: Path = root / "spec" / "blackout_spec.md"
    if spec_file.is_file():
        spec_text: str = spec_file.read_text(encoding="utf-8")
    else:
        spec_text = SPEC_PATH.read_text(encoding="utf-8")
    if feedback is None:
        return spec_text
    project: str = _collect_project(allow_infra, root)
    return spec_text + "\n\n# Current project\n" + project + "\n\n# Feedback\n" + feedback + "\n\nReturn only files that must change."


def _next_run_path() -> Path:
    """Next muse_runs/run_NN.json path."""
    RUNS_DIR.mkdir(parents=True, exist_ok=True)
    existing: list[Path] = sorted(RUNS_DIR.glob("run_*.json"))
    num: int = len(existing) + 1
    while (RUNS_DIR / f"run_{num:02d}.json").exists():
        num += 1
    return RUNS_DIR / f"run_{num:02d}.json"


def main(argv: list[str] | None = None) -> None:
    """CLI entrypoint."""
    parser: argparse.ArgumentParser = argparse.ArgumentParser(description="Generate project with Muse")
    parser.add_argument("--feedback", default=None, help="Feedback file")
    parser.add_argument("--model", default=DEFAULT_MODEL)
    parser.add_argument("--max-usd", type=float, default=30.0)
    parser.add_argument("--allow-infra", action="store_true")
    args: argparse.Namespace = parser.parse_args(argv)
    spent_before: float = spent_usd()
    if spent_before >= float(args.max_usd):
        logger.error("refusing to start: spent $%.4f at or past max $%.2f", spent_before, float(args.max_usd))
        sys.exit(1)
    feedback_text: str | None = None
    if args.feedback is not None:
        feedback_text = Path(str(args.feedback)).read_text(encoding="utf-8")
    prompt: str = build_input(feedback_text, bool(args.allow_infra))
    try:
        files: list[dict[str, str]]
        raw: str
        files, raw = generate(str(args.model), prompt)
    except Exception as exc:
        logger.error("generation failed: %s", exc)
        sys.exit(1)
    run_path: Path = _next_run_path()
    try:
        run_path.write_text(json.dumps({"model": str(args.model), "raw": raw}), encoding="utf-8")
    except OSError as exc:
        logger.error("cannot save run: %s", exc)
        sys.exit(1)
    try:
        written: list[str] = write_files(files, ROOT, bool(args.allow_infra))
    except ValueError as exc:
        logger.error("bad paths: %s", exc)
        sys.exit(1)
    except OSError as exc:
        logger.error("write failed: %s", exc)
        sys.exit(1)
    spent_after: float = spent_usd()
    logger.info("wrote files: %s", ", ".join(written))
    logger.info("this run cost $%.4f, total $%.4f", spent_after - spent_before, spent_after)


if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO)
    main()
